/* SPDX-License-Identifier: Apache-2.0
 * mosaic video web — emit one self-contained HTML page that plays an MVID clip
 * in any browser, with no server, no MIME types and no network: the decoder
 * (web/mvid.js) is inlined at build time and the clip is base64 in the page.
 * Mail it, host it, open it from disk. Also usable from an <iframe>.
 */
#include "mvid.h"
#include "web_mvid_js.h"   /* generated by cmake/embed_web.cmake */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static const char B64[] =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static char *b64_encode(const uint8_t *d, size_t n, size_t *out_len)
{
    size_t o = ((n + 2u) / 3u) * 4u;
    char *s = (char *)malloc(o + 1u);
    if (!s) return NULL;
    size_t i = 0, k = 0;
    for (; i + 2u < n; i += 3u) {
        unsigned v = ((unsigned)d[i] << 16) | ((unsigned)d[i + 1] << 8) | d[i + 2];
        s[k++] = B64[(v >> 18) & 63u];
        s[k++] = B64[(v >> 12) & 63u];
        s[k++] = B64[(v >> 6) & 63u];
        s[k++] = B64[v & 63u];
    }
    if (i < n) {
        unsigned v = (unsigned)d[i] << 16;
        if (i + 1u < n) v |= (unsigned)d[i + 1] << 8;
        s[k++] = B64[(v >> 18) & 63u];
        s[k++] = B64[(v >> 12) & 63u];
        s[k++] = (i + 1u < n) ? B64[(v >> 6) & 63u] : '=';
        s[k++] = '=';
    }
    s[k] = 0;
    if (out_len) *out_len = k;
    return s;
}

/* Page titles go into markup and the <title>: keep only safe characters. */
static void sanitize(const char *in, char *out, size_t cap)
{
    size_t k = 0;
    for (; in && *in && k + 1u < cap; in++) {
        unsigned char c = (unsigned char)*in;
        out[k++] = (char)((c >= 32 && c < 127 && c != '<' && c != '>' &&
                           c != '&' && c != '"' && c != '\'') ? c : '_');
    }
    out[k] = 0;
}

static const char *HEAD_A =
    "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n"
    "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n"
    "<title>";

static const char *HEAD_B =
    "</title>\n<style>\n"
    ":root{--bg:#0b0d12;--ink:#e9edf6;--dim:#8d95a9;--line:#232838;--hot:#5ee0c0}\n"
    "*{box-sizing:border-box}\n"
    "html,body{margin:0;background:var(--bg);color:var(--ink)}\n"
    "body{min-height:100vh;display:grid;place-items:center;padding:28px;"
    "font:15px/1.5 ui-sans-serif,system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;"
    "background:radial-gradient(1100px 560px at 50% -12%,#151b2c,#0b0d12 62%)}\n"
    "main{width:min(760px,100%)}\n"
    "h1{margin:0 0 14px;font:600 12px/1.2 ui-monospace,SFMono-Regular,Menlo,monospace;"
    "letter-spacing:.2em;text-transform:uppercase;color:var(--dim)}\n"
    "h1 b{color:var(--hot);font-weight:600}\n"
    ".bezel{padding:14px;border:1px solid var(--line);border-radius:16px;background:#04060a;"
    "box-shadow:0 34px 90px -34px #000,inset 0 1px 0 #ffffff12}\n"
    "canvas{display:block;width:100%;height:auto;image-rendering:pixelated;"
    "border-radius:8px;background:#000;cursor:pointer}\n"
    ".meta{display:flex;flex-wrap:wrap;gap:3px 14px;margin:13px 2px 0;color:var(--dim);"
    "font:12px/1.5 ui-monospace,Menlo,monospace}\n"
    ".meta b{color:var(--ink);font-weight:600}\n"
    ".hint{margin:9px 2px 0;color:#5c6478;font-size:12px}\n"
    "kbd{font:11px ui-monospace,Menlo,monospace;border:1px solid var(--line);"
    "border-bottom-width:2px;border-radius:4px;padding:1px 5px;color:var(--dim)}\n"
    "</style>\n</head>\n<body>\n<main>\n<h1>Mosaic <b>&middot;</b> MVID v1</h1>\n"
    "<div class=\"bezel\"><canvas id=\"mvid\"></canvas></div>\n"
    "<div class=\"meta\">";

static const char *PAGE_MID =
    "</div>\n<p class=\"hint\">click to pause &middot; <kbd>space</kbd> pause &middot; "
    "<kbd>&larr;</kbd><kbd>&rarr;</kbd> step</p>\n</main>\n"
    "<script type=\"text/mvid-b64\" id=\"mvid-b64\">";

static const char *SCRIPT_OPEN = "</script>\n<script>\n";

static const char *BOOT_A =
    "\n</script>\n<script>\n(function(){"
    "var t=document.getElementById('mvid-b64').textContent.trim();"
    "var s=atob(t),u=new Uint8Array(s.length);"
    "for(var i=0;i<s.length;i++)u[i]=s.charCodeAt(i);"
    "var c=document.getElementById('mvid');var p=MVID.play(c,u,{loop:";

static const char *BOOT_B =
    ",autoplay:true});window.player=p;"
    "c.addEventListener('click',function(){p.playing?p.pause():p.play();});"
    "document.addEventListener('keydown',function(e){"
    "if(e.key===' '){e.preventDefault();p.playing?p.pause():p.play();}"
    "else if(e.key==='ArrowRight')p.step(1);"
    "else if(e.key==='ArrowLeft')p.step(-1);});})();\n"
    "</script>\n</body>\n</html>\n";

int mosaic_video_web(int argc, char **argv)
{
    const char *in = NULL, *out = NULL, *title = NULL;
    int loop = 1;
    for (int i = 3; i < argc; i++) {
        if (!strcmp(argv[i], "--out") && i + 1 < argc) out = argv[++i];
        else if (!strcmp(argv[i], "--title") && i + 1 < argc) title = argv[++i];
        else if (!strcmp(argv[i], "--once")) loop = 0;
        else if (!strcmp(argv[i], "--loop")) loop = 1;
        else if (!in) in = argv[i];
    }
    if (!in || !out) {
        fprintf(stderr, "usage: mosaic video web clip.mvid --out page.html "
                        "[--title T] [--once]\n");
        return 1;
    }
    size_t sz = 0;
    uint8_t *b = mvid_read_file(in, &sz);
    if (!b) { fprintf(stderr, "cannot read %s\n", in); return 2; }
    int rc = mvid_check(b, sz);
    if (rc != MVID_E_OK) {
        fprintf(stderr, "%s: %s\n", in, mvid_err_str(rc));
        free(b);
        return 3;
    }
    mvid_info_t inf;
    mvid_parse(&inf, b, sz);
    size_t b64len = 0;
    char *b64 = b64_encode(b, sz, &b64len);
    if (!b64) { fprintf(stderr, "out of memory\n"); free(b); return 5; }

    char t[200];
    sanitize(title ? title : "Mosaic clip", t, sizeof t);
    char qnote[96];
    qnote[0] = 0;
    if (inf.flags & MVID_F_QFA)
        snprintf(qnote, sizeof qnote, "<span>QFA %ux%u coded, &times;2</span>",
                 inf.width, inf.height);
    char meta[320];
    snprintf(meta, sizeof meta,
             "<b>%ux%u</b><span>%u frames</span><span>%u fps</span>"
             "<span>%u bpp</span><span>%.1f KB</span><span>%.0f B/frame</span>%s",
             inf.width, inf.height, inf.frames, inf.fps, inf.bpp,
             sz / 1024.0, sz / (double)inf.frames, qnote);

    FILE *f = fopen(out, "wb");
    if (!f) { fprintf(stderr, "cannot write %s\n", out); free(b64); free(b); return 4; }
    fputs(HEAD_A, f);
    fputs(t, f);
    fputs(HEAD_B, f);
    fputs(meta, f);
    fputs(PAGE_MID, f);
    fwrite(b64, 1, b64len, f);
    fputs(SCRIPT_OPEN, f);
    fwrite(k_mvid_js, 1, (size_t)k_mvid_js_len, f);
    fputs(BOOT_A, f);
    fputs(loop ? "true" : "false", f);
    fputs(BOOT_B, f);
    long page = ftell(f);
    int ok = (fclose(f) == 0);
    if (!ok) { fprintf(stderr, "short write to %s\n", out); free(b64); free(b); return 4; }

    printf("wrote %s: %dx%d %ubpp, %u frames @ %u fps, clip %.1f KB, page %.1f KB, loop %s\n",
           out, inf.width, inf.height, inf.bpp, inf.frames, inf.fps,
           sz / 1024.0, page / 1024.0, loop ? "on" : "off");
    free(b64);
    free(b);
    return 0;
}
